import java.nio.charset.StandardCharsets;
import java.util.zip.CRC32;

/**
 * Hello world that uses java.util.zip.CRC32 once: the C generated by TeaVM crashes at the
 * first use of the CRC32 when it is compiled by gcc 15 (see README.md).
 *
 * Expected output: Hello, world! CRC32 = ebe6c6e6
 */
public final class Hello {

	public static void main(String[] args) {
		final CRC32 crc = new CRC32();
		crc.update("Hello, world!".getBytes(StandardCharsets.ISO_8859_1));
		System.out.println("Hello, world! CRC32 = " + Long.toHexString(crc.getValue()));
	}
}
